import{_ as e,o as r,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"隐私、合规与负责任 AI","description":"沿数据生命周期治理 Agent 的个人数据、跨租户访问、供应商处理、保留删除、透明度、人工监督与风险责任。","frontmatter":{"title":"隐私、合规与负责任 AI","description":"沿数据生命周期治理 Agent 的个人数据、跨租户访问、供应商处理、保留删除、透明度、人工监督与风险责任。","verified_at":"2026-07-31","source":["https://www.nist.gov/itl/ai-risk-management-framework","https://oecd.ai/en/ai-principles","https://www.iso.org/standard/81230.html","https://www.nist.gov/privacy-framework"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/quality/security-governance/privacy-compliance-responsible-ai.md","filePath":"py-agent/quality/security-governance/privacy-compliance-responsible-ai.md","lastUpdated":1785589115000}'),l={name:"py-agent/quality/security-governance/privacy-compliance-responsible-ai.md"};function t(s,a,o,h,p,c){return r(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="隐私、合规与负责任-ai" tabindex="-1">隐私、合规与负责任 AI <a class="header-anchor" href="#隐私、合规与负责任-ai" aria-label="Permalink to &quot;隐私、合规与负责任 AI&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 会把对话、文件、工具结果、记忆和 Trace 连接起来，数据用途比普通问答更复杂。治理目标不是在上线前勾选一份法规清单，而是让每类数据从收集到删除都有合法目的、最小范围、明确所有者和可验证控制。</p><p>本章提供工程治理框架，不构成特定司法辖区的法律意见。适用法律、行业标准和合同义务应由组织的法律与合规责任人确认。</p><h2 id="_1-数据生命周期" tabindex="-1">1. 数据生命周期 <a class="header-anchor" href="#_1-数据生命周期" aria-label="Permalink to &quot;1. 数据生命周期&quot;">​</a></h2><h3 id="_1-1-收集" tabindex="-1">1.1 收集 <a class="header-anchor" href="#_1-1-收集" aria-label="Permalink to &quot;1.1 收集&quot;">​</a></h3><p>记录数据来自用户输入、上传文件、外部系统、检索库、工具响应还是推断结果。对每个字段声明目的、必要性、合法处理依据和是否可选。</p><h3 id="_1-2-使用" tabindex="-1">1.2 使用 <a class="header-anchor" href="#_1-2-使用" aria-label="Permalink to &quot;1.2 使用&quot;">​</a></h3><p>区分完成当前请求、个性化记忆、质量评测、产品分析、训练/微调和安全审计。用户同意把数据用于完成任务，不自动等于同意把数据用于模型训练。</p><h3 id="_1-3-共享" tabindex="-1">1.3 共享 <a class="header-anchor" href="#_1-3-共享" aria-label="Permalink to &quot;1.3 共享&quot;">​</a></h3><p>模型供应商、云平台、标注团队、日志平台和外部工具都可能成为数据接收方。记录传输内容、地域、子处理者、合同限制和删除机制。</p><h3 id="_1-4-保留与删除" tabindex="-1">1.4 保留与删除 <a class="header-anchor" href="#_1-4-保留与删除" aria-label="Permalink to &quot;1.4 保留与删除&quot;">​</a></h3><p>会话、业务记录、Checkpoint、Store、向量索引、缓存、日志、备份和评测数据有不同保留期。删除请求要传播到所有可定位副本；备份无法即时删除时，应记录隔离和自然过期策略。</p><h2 id="_2-数据清单与分类" tabindex="-1">2. 数据清单与分类 <a class="header-anchor" href="#_2-数据清单与分类" aria-label="Permalink to &quot;2. 数据清单与分类&quot;">​</a></h2><h3 id="_2-1-数据地图" tabindex="-1">2.1 数据地图 <a class="header-anchor" href="#_2-1-数据地图" aria-label="Permalink to &quot;2.1 数据地图&quot;">​</a></h3><p>一条用户消息可能派生出 Embedding、摘要、长期记忆、Trace、缓存和标注样本。数据地图应包含原始数据与派生产物，不能只登记业务数据库。</p><h3 id="_2-2-分类" tabindex="-1">2.2 分类 <a class="header-anchor" href="#_2-2-分类" aria-label="Permalink to &quot;2.2 分类&quot;">​</a></h3><p>可按公开、内部、机密、受限分级，并附个人数据、认证 Secret、健康/财务等专题标签。分类决定允许的模型、地域、日志方式、加密、访问和保留。</p><h3 id="_2-3-推断数据" tabindex="-1">2.3 推断数据 <a class="header-anchor" href="#_2-3-推断数据" aria-label="Permalink to &quot;2.3 推断数据&quot;">​</a></h3><p>模型推断出的偏好、风险标签或用户画像也可能具有隐私影响，即使它不是用户直接填写。必须记录来源、置信度、用途和纠正机制。</p><h2 id="_3-最小化与目的限制" tabindex="-1">3. 最小化与目的限制 <a class="header-anchor" href="#_3-最小化与目的限制" aria-label="Permalink to &quot;3. 最小化与目的限制&quot;">​</a></h2><h3 id="_3-1-输入最小化" tabindex="-1">3.1 输入最小化 <a class="header-anchor" href="#_3-1-输入最小化" aria-label="Permalink to &quot;3.1 输入最小化&quot;">​</a></h3><p>在调用模型和工具前，只选择完成任务必需字段。不要把完整客户对象、全部历史对话或整份数据库记录发送给模型。</p><h3 id="_3-2-上下文最小化" tabindex="-1">3.2 上下文最小化 <a class="header-anchor" href="#_3-2-上下文最小化" aria-label="Permalink to &quot;3.2 上下文最小化&quot;">​</a></h3><p>检索按租户、身份、文档 ACL 和目的过滤；长期记忆只取当前任务相关项；系统 Secret 永不进入上下文。更大上下文不等于更好，反而扩大泄露面和成本。</p><h3 id="_3-3-日志最小化" tabindex="-1">3.3 日志最小化 <a class="header-anchor" href="#_3-3-日志最小化" aria-label="Permalink to &quot;3.3 日志最小化&quot;">​</a></h3><p>默认记录事件元数据、哈希、分类标签和受控摘要；全文采样需要单独权限与保留期。敏感字段遮蔽应在日志出口前执行，不能依赖查询时隐藏。</p><h3 id="_3-4-假名化与匿名化" tabindex="-1">3.4 假名化与匿名化 <a class="header-anchor" href="#_3-4-假名化与匿名化" aria-label="Permalink to &quot;3.4 假名化与匿名化&quot;">​</a></h3><p>替换直接标识符是“假名化”，若仍可通过映射或组合重新识别，就不是匿名。真正匿名化很难，应通过重识别风险评估，而不是删除姓名后直接宣称匿名。</p><h2 id="_4-访问与租户隔离" tabindex="-1">4. 访问与租户隔离 <a class="header-anchor" href="#_4-访问与租户隔离" aria-label="Permalink to &quot;4. 访问与租户隔离&quot;">​</a></h2><h3 id="_4-1-身份传播" tabindex="-1">4.1 身份传播 <a class="header-anchor" href="#_4-1-身份传播" aria-label="Permalink to &quot;4.1 身份传播&quot;">​</a></h3><p>认证后的 Principal 在 API、Agent、工具、数据层和异步任务中保持一致。队列消息只携带必要引用，Worker 重新加载可信权限，不接受模型或消息正文自报身份。</p><h3 id="_4-2-数据层强制" tabindex="-1">4.2 数据层强制 <a class="header-anchor" href="#_4-2-数据层强制" aria-label="Permalink to &quot;4.2 数据层强制&quot;">​</a></h3><p>租户条件应成为 Repository、行级安全或独立存储边界的一部分。向量索引也要在召回阶段实施授权过滤，不能先召回其他租户内容再期待模型忽略。</p><h3 id="_4-3-最小权限与职责分离" tabindex="-1">4.3 最小权限与职责分离 <a class="header-anchor" href="#_4-3-最小权限与职责分离" aria-label="Permalink to &quot;4.3 最小权限与职责分离&quot;">​</a></h3><p>开发、运维、标注、客服和安全调查人员访问不同数据。高敏导出、策略变更和删除可要求双人审批，审计人员不能轻易修改审计记录。</p><h2 id="_5-供应商与模型治理" tabindex="-1">5. 供应商与模型治理 <a class="header-anchor" href="#_5-供应商与模型治理" aria-label="Permalink to &quot;5. 供应商与模型治理&quot;">​</a></h2><h3 id="_5-1-供应商评估" tabindex="-1">5.1 供应商评估 <a class="header-anchor" href="#_5-1-供应商评估" aria-label="Permalink to &quot;5.1 供应商评估&quot;">​</a></h3><p>确认数据是否用于训练、默认保留期、可用地域、加密、访问控制、子处理者、事件通知、删除与导出能力。产品设置和合同可能不同，应记录实际账户配置。</p><h3 id="_5-2-模型路由" tabindex="-1">5.2 模型路由 <a class="header-anchor" href="#_5-2-模型路由" aria-label="Permalink to &quot;5.2 模型路由&quot;">​</a></h3><p>路由策略先检查数据分类和地域，再比较能力、成本和延迟。受限数据不能因主模型限流就自动降级到未批准供应商。</p><h3 id="_5-3-开源与私有部署" tabindex="-1">5.3 开源与私有部署 <a class="header-anchor" href="#_5-3-开源与私有部署" aria-label="Permalink to &quot;5.3 开源与私有部署&quot;">​</a></h3><p>私有部署减少向外部供应商传输，但不会自动解决内部访问、日志、训练数据版权、模型泄露和运维安全。部署位置只是治理决策的一部分。</p><h2 id="_6-用户权利与数据操作" tabindex="-1">6. 用户权利与数据操作 <a class="header-anchor" href="#_6-用户权利与数据操作" aria-label="Permalink to &quot;6. 用户权利与数据操作&quot;">​</a></h2><p>系统应能回答某主体的数据存在哪里、为何处理、能否导出、更正、删除或停止某用途。为每类数据建立稳定主体关联和删除传播流程；无法关联的数据就难以履行请求。</p><p>长期记忆尤其需要可查看、修改、关闭和删除。模型生成的错误记忆不能成为不可纠正的“系统事实”。删除后要验证检索、缓存和新会话不再返回该信息。</p><h2 id="_7-透明度与人工监督" tabindex="-1">7. 透明度与人工监督 <a class="header-anchor" href="#_7-透明度与人工监督" aria-label="Permalink to &quot;7. 透明度与人工监督&quot;">​</a></h2><h3 id="_7-1-透明度" tabindex="-1">7.1 透明度 <a class="header-anchor" href="#_7-1-透明度" aria-label="Permalink to &quot;7.1 透明度&quot;">​</a></h3><p>向用户说明正在与 AI 交互、系统能做什么、重要限制、数据用途和如何申诉。不要披露可被滥用的内部安全细节，但也不能让用户误以为输出经过人工核准。</p><h3 id="_7-2-人在回路" tabindex="-1">7.2 人在回路 <a class="header-anchor" href="#_7-2-人在回路" aria-label="Permalink to &quot;7.2 人在回路&quot;">​</a></h3><p>人工监督不是在界面加一个“确认”按钮。确认者必须看到足够证据、有真实否决权、时间和能力，并且系统不能通过默认值诱导盲目批准。</p><h3 id="_7-3-可解释证据" tabindex="-1">7.3 可解释证据 <a class="header-anchor" href="#_7-3-可解释证据" aria-label="Permalink to &quot;7.3 可解释证据&quot;">​</a></h3><p>对高影响决策保存输入来源、适用政策、工具结果、模型与版本、最终责任人。模型自然语言解释可能是事后生成，不能替代真实 Trace 和决策规则。</p><h2 id="_8-公平性、伤害与适用边界" tabindex="-1">8. 公平性、伤害与适用边界 <a class="header-anchor" href="#_8-公平性、伤害与适用边界" aria-label="Permalink to &quot;8. 公平性、伤害与适用边界&quot;">​</a></h2><h3 id="_8-1-影响分析" tabindex="-1">8.1 影响分析 <a class="header-anchor" href="#_8-1-影响分析" aria-label="Permalink to &quot;8.1 影响分析&quot;">​</a></h3><p>按受影响人群、决策重要性、可逆性和规模评估潜在伤害。评测需要覆盖关键人群 Slice，但敏感属性的收集本身也要有合法目的和保护。</p><h3 id="_8-2-自动化边界" tabindex="-1">8.2 自动化边界 <a class="header-anchor" href="#_8-2-自动化边界" aria-label="Permalink to &quot;8.2 自动化边界&quot;">​</a></h3><p>高影响的资格、就业、信贷、医疗或法律决策可能需要更严格限制、专业审核或禁止全自动化。不能因为模型平均准确率高就忽略个体救济和错误成本。</p><h3 id="_8-3-内容来源与知识产权" tabindex="-1">8.3 内容来源与知识产权 <a class="header-anchor" href="#_8-3-内容来源与知识产权" aria-label="Permalink to &quot;8.3 内容来源与知识产权&quot;">​</a></h3><p>记录训练、微调、RAG 和输出使用的数据来源、许可与引用要求。公开可访问不等于可无限复制、训练或再分发。</p><h2 id="_9-治理流程" tabindex="-1">9. 治理流程 <a class="header-anchor" href="#_9-治理流程" aria-label="Permalink to &quot;9. 治理流程&quot;">​</a></h2><h3 id="_9-1-风险分级" tabindex="-1">9.1 风险分级 <a class="header-anchor" href="#_9-1-风险分级" aria-label="Permalink to &quot;9.1 风险分级&quot;">​</a></h3><p>按数据敏感度、工具权限、用户影响、规模和可逆性分级。风险越高，要求越强的数据评估、安全测试、人工监督、发布审批和持续监控。</p><h3 id="_9-2-变更评审" tabindex="-1">9.2 变更评审 <a class="header-anchor" href="#_9-2-变更评审" aria-label="Permalink to &quot;9.2 变更评审&quot;">​</a></h3><p>新增数据源、供应商、模型、工具、记忆用途、地域或自动化权限时触发隐私和 AI 风险复查。仅代码实现变化并不是唯一触发条件。</p><h3 id="_9-3-事件响应" tabindex="-1">9.3 事件响应 <a class="header-anchor" href="#_9-3-事件响应" aria-label="Permalink to &quot;9.3 事件响应&quot;">​</a></h3><p>预先定义泄露、跨租户访问、错误高影响动作、模型异常和政策绕过的分级、遏制、通知、取证和修复流程。日志保留既要支持调查，也要遵守最小化与保留限制。</p><h2 id="_10-填写后的数据记录" tabindex="-1">10. 填写后的数据记录 <a class="header-anchor" href="#_10-填写后的数据记录" aria-label="Permalink to &quot;10. 填写后的数据记录&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据：客服会话正文</span></span>
<span class="line"><span>目的：回答当前问题；经单独批准后用于质量抽检</span></span>
<span class="line"><span>来源/主体：已认证用户</span></span>
<span class="line"><span>分类：机密 + 个人数据</span></span>
<span class="line"><span>存储：业务库 30 天；Trace 正文抽样 7 天；指标仅聚合</span></span>
<span class="line"><span>接收方：批准的模型供应商（禁训练配置）</span></span>
<span class="line"><span>访问：所属租户客服；抽检人员按工单临时授权</span></span>
<span class="line"><span>删除：业务库 -&gt; Trace 样本 -&gt; 向量派生 -&gt; 缓存失效</span></span>
<span class="line"><span>控制验证：季度抽样、跨租户测试、删除演练</span></span>
<span class="line"><span>所有者：客服产品数据负责人</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="_11-常见误区" tabindex="-1">11. 常见误区 <a class="header-anchor" href="#_11-常见误区" aria-label="Permalink to &quot;11. 常见误区&quot;">​</a></h2><ol><li><strong>隐私等于给日志打码</strong>：收集目的、供应商共享和删除仍未治理。</li><li><strong>用户同意覆盖所有用途</strong>：不同目的可能需要分别说明和选择。</li><li><strong>私有化部署自动合规</strong>：内部权限与数据生命周期风险仍存在。</li><li><strong>删除原始文本就完成删除</strong>：Embedding、摘要、记忆和评测副本可能仍在。</li><li><strong>人工确认自动等于负责</strong>：没有证据和否决权只是形式监督。</li></ol><h2 id="_12-治理检查表" tabindex="-1">12. 治理检查表 <a class="header-anchor" href="#_12-治理检查表" aria-label="Permalink to &quot;12. 治理检查表&quot;">​</a></h2><ul><li>原始与派生数据是否都有来源、目的、分类和所有者；</li><li>模型、工具、日志和标注平台是否执行最小化；</li><li>租户权限是否在检索和数据层强制；</li><li>供应商实际保留、训练和地域配置是否已确认；</li><li>查阅、更正、删除和停止处理是否能端到端验证；</li><li>高影响功能是否有适当人工监督和申诉机制；</li><li>新模型、工具、数据源和用途是否触发复查。</li></ul><p>负责任 AI 不是抽象价值声明，而是一套从数据、能力到责任人的可验证约束。只有控制能够沿生命周期执行并留下证据，组织才能说明系统为什么被允许运行，以及何时必须停止或改变它。</p>`,74)])])}const b=e(l,[["render",t]]);export{u as __pageData,b as default};
